def spongecase(word: str) -> str:
    letters = []
    for i, ch in enumerate(word):
        if i % 2 == 0:
            letters.append(ch.lower())
        else:
            letters.append(ch.upper())
    return "".join(letters)


word = input().strip()
print(spongecase(word))

