#include <cctype>
#include <iostream>
#include <string>

std::string spongecase(const std::string& word) {
    std::string result;
    for (std::size_t i = 0; i < word.size(); i++) {
        unsigned char ch = static_cast<unsigned char>(word[i]);
        if (i % 2 == 0) {
            result += static_cast<char>(std::tolower(ch));
        } else {
            result += static_cast<char>(std::toupper(ch));
        }
    }
    return result;
}

int main() {
    std::string word;
    std::cin >> word;
    std::cout << spongecase(word) << "\n";
    return 0;
}

