package main

import (
	"fmt"
	"strings"
	"unicode"
)

func spongecase(word string) string {
	var result strings.Builder
	for i, ch := range []rune(word) {
		if i%2 == 0 {
			result.WriteRune(unicode.ToLower(ch))
		} else {
			result.WriteRune(unicode.ToUpper(ch))
		}
	}
	return result.String()
}

func main() {
	var word string
	fmt.Scan(&word)
	fmt.Println(spongecase(word))
}

